#ifndef GE_SESSION_DEMO_IO_CONFIG_H
#define GE_SESSION_DEMO_IO_CONFIG_H

#include <cstdint>
#include <string>
#include <vector>

// Runtime configuration loaded from io_config.json (generated by tools/prepare_input.py).
// Only fields actually read at runtime are kept; other io_config.json fields
// (dtype/elem_bytes/runtime_shape/shape/size_bytes) are used by the toolchain only.
struct InputCfg {
  std::string name;
  std::string parser_shape;   // "d0,d1,...", dynamic dims are -1
  std::string hint_shape;     // "idx:[d0,d1,...]"
};

struct OutputCfg {
  int32_t index = 0;
  std::string name;
  std::string dtype;
  int32_t elem_bytes = 0;
  std::vector<int64_t> shape;  // expected shape from io_config; -1 = dynamic (not read by GE)
};

struct IoConfig {
  std::string model_id;
  std::string model_file;      // relative to GE_DEMO_ROOT
  std::string framework = "onnx";
  int64_t batch_size = 1;
  bool pass_input_shape = true;
  std::string shape_mode = "all_static";
  std::string batch_list;      // relative to GE_DEMO_ROOT
  std::string output_dir;      // relative to GE_DEMO_ROOT
  std::vector<InputCfg> inputs;
  std::vector<OutputCfg> outputs;

  static IoConfig Load(const std::string &path);
};

#endif  // GE_SESSION_DEMO_IO_CONFIG_H